        {"상황":"자신의 죄가 너무 커서 용서받지 못할 것 같은 분", "성경원리":"하나님은 노하기를 더디하신다. 그러나 그리스도 안에서 죄의 대가가 치러졌다", "실제적용":"십자가에서 해결된 죄의 문제를 믿음으로 받아들이고 하나님의 은혜를 의심하지 말라"},
        {"상황":"하나님의 전능성을 의심하는 분", "성경원리":"폭풍도 하나님 발의 티끌이다. 어떤 상황도 하나님의 통제 밖에 있지 않다", "실제적용":"자신의 문제를 전능하신 하나님께 맡기고 인간적 한계를 인정하며 기도하라"}
