        {"상황":"자신이 충분히 선하다고 생각하는 분", "성경원리":"바위도 깨는 하나님의 공의 앞에서 어떤 인간도 스스로 설 수 없다", "실제적용":"자신의 선함이 아닌 하나님의 기준 앞에서 자신을 돌아보고 그리스도께 나아가라"},
        {"상황":"하나님의 공의를 이해하지 못하는 분", "성경원리":"하나님의 진노는 도덕 질서를 수호하는 거룩한 반응이다. 죄에 대한 책임이 있기에 진노가 있다", "실제적용":"십자가에서 그리스도가 담당하신 것이 무엇인지 묵상하여 하나님의 공의와 사랑을 함께 이해하라"}
