        {"새찬송가":"419", "통일찬송가":"463", "제목":"내 주는 살아계시고", "선정이유":"살아계셔서 보호하시는 하나님을 신뢰"},
        {"새찬송가":"570", "통일찬송가":"488", "제목":"주는 나를 기르시는 목자", "선정이유":"선한 목자로서 자기 양을 아시는 하나님"}
