        {"구절":"계 21:4", "연결점":"다시는 사망이 없고 애통하는 것이나 곡하는 것이나 아픈 것이 없음", "구분":"신약"},
        {"구절":"마 16:18", "연결점":"음부의 권세가 교회를 이기지 못하리라", "구분":"신약"}
