        {"상황":"반복되는 같은 문제에 낙심한 분", "성경원리":"재난이 두 번 다시 일어나지 않는 하나님의 완전한 구원을 기대하라", "실제적용":"반복되는 문제의 근본 원인을 하나님 앞에서 찾고 완전한 치유를 위해 기도하라"}
