        {"대지":"2대지: 결박을 끊으심 (완전한 자유)", "내용":"복수형의 결박들. 하나의 결박이 아닌 모든 종류의 속박이 끊긴다. 그리스도 안에서의 자유는 포괄적이고 완전하다", "예화_적용":"요 8:36의 '아들이 너희를 자유케 하면 너희가 참으로 자유로우리라'를 설명하라"},
        {"대지":"3대지: 내가 하겠다 (하나님의 직접 개입)", "내용":"하나님이 직접 나서신다. 인간의 노력이나 계획이 아닌 하나님 자신의 능력으로 이루어지는 구원이다", "예화_적용":"인간이 할 수 없는 것을 하나님이 하신 성경 이야기들(홍해 기적, 요단 강 도강 등)을 들어라"},
        {"대지":"결론", "내용":"오늘 당신을 옭아매는 멍에가 있는가? 죄의 멍에, 두려움의 멍에, 관계의 멍에, 중독의 멍에. 하나님이 말씀하신다. 내가 깨뜨리겠다. 그 하나님 앞으로 나아와 멍에를 내려놓아라", "예화_적용":"마 11:28-30의 '내 멍에를 메고 내게 배우라'로 마무리하며 그리스도의 멍에가 쉬움을 선포하라"}
