        {"구분":"이름이 전파되지 않음", "내용":"기억에서 완전히 지워지는 심판", "그리스도연결":"생명책에 이름이 기록된 자들만 기억되는 마지막 심판 (계 20:15, 빌 4:3)"},
        {"구분":"무덤을 예비함", "내용":"죽음을 예정한 하나님의 명령", "그리스도연결":"죽음의 권세를 이기시고 부활하신 그리스도 - 그리스도인에게는 죽음이 끝이 아님 (요 11:25)"}
