        {"상황":"이름과 명예를 위해 사는 분", "성경원리":"앗수르의 이름이 전파되지 않는다. 인간의 이름과 명예는 영원하지 않다", "실제적용":"하나님 앞에서의 이름, 즉 생명책에 기록되는 것을 위해 사는 삶으로 전환하라"},
        {"상황":"우상 숭배적 관습에서 벗어나지 못하는 분", "성경원리":"하나님은 새긴 우상과 부은 우상을 멸절하신다. 어떤 형태의 우상도 하나님 앞에서 살아남지 못한다", "실제적용":"가정에서나 문화에서 우상 숭배적 요소를 제거하고 오직 여호와만 예배하는 결단을 하라"}
