        {"구분":"악인이 진멸되어 통행하지 않음", "내용":"위협의 완전한 제거로 진정한 평화가 실현됨", "그리스도연결":"마지막 날 사탄이 완전히 제거되고 이루어지는 영원한 샬롬 (계 20:10, 계 21:4)"}
