    표5_매튜헨리: [
        {"영어원문":"He that dasheth in pieces is come up against thee — the destroyer appointed by God to execute judgment on Nineveh.", "한국어번역":"파괴하는 자가 네게 올라왔도다 — 니느웨에 심판을 집행하도록 하나님이 임명한 파괴자이다.", "핵심통찰":"하나님의 심판 도구는 이미 임명되어 출동했다"},
        {"영어원문":"Keep the munition, watch the way — this is bitter irony; no preparation will avail against the judgment of God.", "한국어번역":"요새를 지키고 길을 파수하라 — 이것은 쓴 조롱이다. 어떤 준비도 하나님의 심판을 막을 수 없다.", "핵심통찰":"최선의 방어도 하나님의 심판 앞에서는 무력하다"},
        {"영어원문":"God can find instruments of his vengeance when he pleases, and no fortress can resist them.", "한국어번역":"하나님은 원하실 때 복수의 도구를 찾으시며 어떤 요새도 그것을 막을 수 없다.", "핵심통찰":"하나님의 심판 도구는 어떤 방어도 돌파한다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"파괴하는 자가 올라온다 - 막을 수 없는 하나님의 심판", "예화_적용":"하나님의 심판의 불가피성과 동시에 지금의 회개 기회를 강조하라"},
        {"대지":"서론", "내용":"나훔 2장은 니느웨 함락의 생생한 전쟁 보도다. 파괴하는 자가 올라온다. 산성을 지켜라. 허리를 굳게 하라. 그러나 이 모든 조언은 결국 소용이 없다. BC 612년 니느웨는 함락되었다", "예화_적용":"전쟁 영화의 공격 장면처럼 생생하게 묘사하여 긴박감을 전달하라"},
        {"대지":"1대지: 파괴하는 자 (하나님의 심판 도구)", "내용":"메대-바벨론 연합군이 하나님의 심판 도구로 쓰였다. 하나님은 역사의 세력을 사용하여 자신의 뜻을 이루신다", "예화_적용":"바벨론도 하나님의 도구였고 나중에 심판받았음을 연결하여 모든 권세가 하나님 손 안에 있음을 가르쳐라"},
        {"대지":"2대지: 방어를 준비하라 (조롱의 경고)", "내용":"최선을 다해 방어하라. 그러나 소용없다. 하나님의 심판 앞에서 인간의 최선은 무력하다", "예화_적용":"아무리 좋은 안전장치도 인간의 죽음을 막지 못하듯 인간의 방비가 하나님의 심판을 막지 못함을 가르쳐라"},
        {"대지":"3대지: 경고 자체가 은혜 (돌이킬 기회)", "내용":"심판이 오기 전 경고하시는 하나님. 아직 기회가 있다. 지금 돌이키면 된다", "예화_적용":"요나 시대 니느웨가 회개하여 심판을 늦춘 것을 들어 경고는 은혜임을 가르쳐라"},
        {"대지":"결론", "내용":"파괴하는 자가 오기 전에 돌이키라. 지금이 은혜의 때다. 하나님의 심판 앞에서 인간의 방어는 무력하지만 회개는 길을 열어준다", "예화_적용":"벧후 3:9의 하나님이 아무도 멸망하지 않고 다 회개하기를 원하신다는 말씀으로 마무리하라"}
    ],
