        {"새찬송가":"342", "통일찬송가":"370", "제목":"내 주는 강한 성이요", "선정이유":"하나님만이 진정한 방어 요새임"},
        {"새찬송가":"180", "통일찬송가":"174", "제목":"주 예수여 은혜를", "선정이유":"심판 앞에서 은혜를 구하는 간절함"},
        {"새찬송가":"254", "통일찬송가":"499", "제목":"너희 죄 흉악하나", "선정이유":"심판 전 회개로 나아가는 결단"}
