    표8_상담적용: [
        {"상황":"미래의 심판이나 결과를 두려워하지 않고 사는 분", "성경원리":"파괴하는 자가 올라온다. 심판은 반드시 온다. 준비하지 않으면 안 된다", "실제적용":"지금의 삶이 마지막 날 어떤 결과를 낳을지 진지하게 생각하고 회개와 헌신으로 준비하라"},
        {"상황":"자신의 능력으로 문제를 해결하려는 분", "성경원리":"산성을 지키고 허리를 굳게 해도 하나님의 심판을 막을 수 없다. 인간의 능력은 한계가 있다", "실제적용":"자신의 힘을 의지하기보다 하나님께 나아가 도움을 구하라"},
        {"상황":"경고의 말씀을 무시하는 분", "성경원리":"경고하시는 것 자체가 은혜다. 기회가 있을 때 돌이켜야 한다", "실제적용":"설교나 성경을 통해 들리는 경고의 말씀을 진지하게 받아들이고 즉각적으로 반응하라"}
    ],
