        {"구절":"합 1:6", "연결점":"하나님이 바벨론을 심판 도구로 일으키심", "구분":"구약"},
        {"구절":"잠 21:30-31", "연결점":"지혜도 모략도 여호와를 당하지 못하며 말도 전쟁의 승리는 여호와께 있음", "구분":"구약"},
        {"구절":"암 9:2-3", "연결점":"어디에 숨어도 하나님의 심판에서 피할 수 없음", "구분":"구약"},
        {"구절":"마 24:42", "연결점":"깨어 있으라 어느 날에 주가 임할는지 알지 못함", "구분":"신약"},
        {"구절":"계 6:15-17", "연결점":"심판의 날 모든 사람이 숨으려 하지만 피할 수 없음", "구분":"신약"},
        {"구절":"계 19:11-16", "연결점":"심판자로 재림하시는 그리스도", "구분":"신약"},
        {"구절":"벧후 3:9", "연결점":"하나님이 아무도 멸망하지 않고 다 회개하기를 원하심", "구분":"신약"}
