        {"항목":"도망가는 군대", "내용":"BC 612년 니느웨 함락 때 앗수르 군대가 도망했다는 역사 기록이 있다. 서라 서라 하는 명령도 소용없었다", "목회적활용":"공황 상태에 빠진 군대는 명령도 듣지 않는다. 심판의 두려움은 모든 규율을 무너뜨린다"},
        {"항목":"충성의 붕괴", "내용":"돌아보는 자가 없다는 것은 마지막 순간의 충성도 사라짐을 의미한다. 위기 앞에서 인간적 관계의 한계가 드러난다", "목회적활용":"인간의 충성은 한계가 있다. 하나님만이 끝까지 신실하신 분이다"}
