        {"교리":"인간 관계의 한계", "설명":"위기 앞에서 충성도 사라진다. 하나님만이 끝까지 함께하시는 신실한 분이시다", "관련구절":"딤후 4:16, 시 27:10, 시 118:8-9, 히 13:5"}
