        {"구분":"돌아보는 자가 없음", "내용":"충성이 사라지는 심판의 공포", "그리스도연결":"끝까지 함께하시는 그리스도 - 내가 세상 끝날까지 너희와 함께 있으리라 (마 28:20)"}
