        {"원어":"כְּבֹד (케보드)", "의미_문법":"영광/보물 - 명사. 귀중한 기구들과 보화들", "설교포인트":"세상의 모든 영광과 보물은 하나님의 심판 앞에서 전리품이 된다"}
