        {"항목":"저축의 역설", "내용":"무한히 저축했던 것이 무한히 빼앗기는 것이 된다. 더 많이 쌓을수록 심판 때 더 많이 잃는다", "목회적활용":"의롭지 못한 방법으로 쌓은 재물은 결국 모두 잃게 된다"}
