    표5_매튜헨리: [
        {"영어원문":"Take the spoil of silver, take the spoil of gold — the wealth of Nineveh, gathered by oppression, shall now be scattered.", "한국어번역":"은을 노략하라, 금을 노략하라 — 억압으로 모아진 니느웨의 재물이 이제 흩어질 것이다.", "핵심통찰":"불의하게 모은 재물은 결국 흩어진다"},
        {"영어원문":"There is none end of the store — the abundance that once seemed inexhaustible now becomes the spoil of conquerors.", "한국어번역":"저축한 것이 무한하도다 — 한때 무궁무진해 보이던 풍요가 이제 정복자들의 전리품이 된다.", "핵심통찰":"가장 많이 쌓은 자가 가장 많이 잃을 수 있다"},
        {"영어원문":"The glory of Nineveh becomes the plunder of others — no earthly treasure is secure against the judgment of God.", "한국어번역":"니느웨의 영광이 다른 자들의 약탈물이 된다 — 어떤 세상 보물도 하나님의 심판에 대항해 안전할 수 없다.", "핵심통찰":"세상 보물은 하나님의 심판 앞에서 안전하지 않다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"은을 노략하라 금을 노략하라 - 불의한 재물의 최후", "예화_적용":"재물의 일시성과 하나님의 경제 공의를 선포하라"},
        {"대지":"서론", "내용":"앗수르는 수백 년 동안 정복 전쟁으로 엄청난 재물을 쌓았다. 무한하고 끝이 없다고 할 정도로. 그러나 BC 612년 하루아침에 모두 빼앗겼다. 하나님의 공의는 불의하게 쌓인 재물도 심판하신다", "예화_적용":"부정부패로 쌓은 재물이 결국 몰수되거나 사라지는 역사적 사례들을 들어 하나님의 경제 공의를 가르쳐라"},
        {"대지":"1대지: 은과 금의 노략 (불의한 재물의 심판)", "내용":"앗수르가 노략하여 쌓은 것이 노략당한다. 심은 대로 거둔다. 불의한 재물은 불의하게 빼앗긴다", "예화_적용":"역사에서 부정한 방법으로 부를 쌓은 권력자들의 말로를 들어 공의의 원칙을 가르쳐라"},
        {"대지":"2대지: 무한한 저축물 (재물의 허무함)", "내용":"무한해 보였던 것이 순식간에 사라진다. 재물은 영원한 안전을 보장하지 않는다. 하나님만이 영원한 안전이다", "예화_적용":"눅 12:20의 어리석은 부자 이야기로 쌓기만 하는 삶의 어리석음을 가르쳐라"},
        {"대지":"3대지: 아름다운 기구들 (세상 영광의 일시성)", "내용":"세상의 아름다운 것들도 심판 앞에서 전리품이 된다. 세상 영광보다 하늘의 영광에 투자하라", "예화_적용":"마 6:19-20의 하늘에 보물을 쌓으라는 말씀으로 영원한 투자를 권면하라"},
        {"대지":"결론", "내용":"재물을 쌓는 것이 나쁜 것이 아니다. 그러나 어떻게 쌓는가, 그 재물이 어디를 향하는가가 중요하다. 불의하게 쌓은 것은 빼앗기고 하나님 나라를 위해 사용한 것은 영원히 남는다", "예화_적용":"마 6:20-21의 네 보물 있는 곳에 네 마음도 있다는 말씀으로 마음의 방향을 점검하게 하라"}
    ],
