        {"구절":"빌 2:4", "연결점":"각각 자기 일을 돌볼 뿐더러 남의 일도 돌보라", "구분":"신약"},
        {"구절":"빌 2:7", "연결점":"그리스도가 자기를 비워 종의 형체를 가지심 - 자발적 비움", "구분":"신약"},
        {"구절":"고전 13:5", "연결점":"사랑은 자기의 유익을 구하지 않음", "구분":"신약"}
