        {"새찬송가":"209", "통일찬송가":"166", "제목":"죄악에서 우리를", "선정이유":"죄와 폭력에서 구원하시는 하나님"},
        {"새찬송가":"309", "통일찬송가":"414", "제목":"아 내 맘속에", "선정이유":"피 성이 아닌 의의 성으로 변화된 마음"},
        {"새찬송가":"295", "통일찬송가":"398", "제목":"내 죄 사함 받고서", "선정이유":"죄악에서 돌이켜 용서받는 은혜"}
