        {"교리":"죄의 대가", "설명":"무수한 시체들은 니느웨의 죄악이 가져온 결과다. 죄의 삯은 사망이다", "관련구절":"롬 6:23, 창 2:17, 사 3:11, 렘 21:9"},
        {"교리":"역사 안의 심판", "설명":"하나님의 심판은 내세만의 일이 아니라 역사 안에서도 구체적으로 이루어진다", "관련구절":"신 28:15-68, 암 4:6-11, 렘 5:15-17, 사 10:5-6"}
