    표4_예표론: [
        {"구분":"번쩍이는 칼", "내용":"심판의 날카로운 칼이 번쩍임", "그리스도연결":"하나님의 말씀은 좌우에 날선 검 - 죄를 드러내는 심판의 말씀 (히 4:12)"},
        {"구분":"무수한 시체", "내용":"심판의 결과로 쌓이는 죽음들", "그리스도연결":"모든 죄의 결과인 사망을 이기신 그리스도 - 첫 번째 부활 (계 20:6, 고전 15:54)"},
        {"구분":"시체에 걸려 넘어짐", "내용":"죽음이 압도하는 참혹한 장면", "그리스도연결":"걸려 넘어지는 돌이 되신 그리스도 - 구원 혹은 심판의 돌 (눅 20:18, 벧전 2:8)"}
    ],
    표5_매튜헨리: [
        {"영어원문":"There is a multitude of slain — God makes short work of his enemies; the proud city is filled with the dead.", "한국어번역":"살육 당한 무리가 많도다 — 하나님은 그의 원수들을 빠르게 처리하신다. 교만한 성이 시체로 가득하다.", "핵심통찰":"하나님의 심판이 임할 때 강한 자들이 순식간에 무너진다"},
        {"영어원문":"They stumble upon their corpses — so complete is the slaughter that even the survivors trip over the dead.", "한국어번역":"그들이 시체에 걸려 넘어지도다 — 살육이 너무 완전하여 살아남은 자들조차 죽은 자들 위에 걸려 넘어진다.", "핵심통찰":"심판의 완전성은 도망가는 것조차 불가능하게 한다"},
        {"영어원문":"This is the fruit of all their cruelty; they have filled other lands with slain, and now their own land is filled.", "한국어번역":"이것이 그들의 잔인함의 열매이다. 그들은 다른 나라들을 살육으로 채웠고 이제 그들의 땅이 채워진다.", "핵심통찰":"자신이 저지른 것이 자신에게 돌아온다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"시체 무더기에 걸려 넘어지다 - 죄의 결과와 심판의 현실", "예화_적용":"죄의 결과가 얼마나 처참한지를 통해 회개와 복음을 선포하라"},
        {"대지":"서론", "내용":"전쟁 사진에서 가장 충격적인 것은 시체다. 나훔은 니느웨 함락 현장에서 시체가 너무 많아 걸려 넘어진다고 묘사한다. 이것이 죄악의 결말이다. 폭력으로 세운 제국이 폭력으로 무너진다", "예화_적용":"전쟁 다큐멘터리나 역사 사진을 통해 전쟁의 참혹함을 실제로 느끼게 하라"},
        {"대지":"1대지: 번쩍이는 칼 (죄를 드러내는 심판)", "내용":"번쩍이는 칼은 히 4:12의 좌우에 날선 검인 하나님의 말씀을 연상시킨다. 심판은 모든 것을 드러낸다", "예화_적용":"히 4:12-13을 읽으며 하나님 앞에 모든 것이 드러남을 가르쳐라"},
        {"대지":"2대지: 무수한 시체 (죄의 대가)", "내용":"롬 6:23의 죄의 삯은 사망이다. 앗수르의 죄가 죽음을 불러왔다. 죄는 반드시 죽음의 결과를 낳는다", "예화_적용":"죄의 결과가 단지 개인이 아닌 공동체 전체에 미치는 것을 역사적 사례로 가르쳐라"},
        {"대지":"3대지: 시체에 걸려 넘어짐 (도망도 불가능)", "내용":"시체가 너무 많아 걸려 넘어진다. 심판이 완전하다. 도망의 여지가 없다. 그러나 그리스도 안에는 피난처가 있다", "예화_적용":"걸려 넘어지는 돌이신 그리스도를 예로 들어 심판과 구원이 동일한 분임을 가르쳐라"},
        {"대지":"결론", "내용":"죄는 반드시 결과를 낳는다. 무수한 시체가 그것을 증명한다. 그러나 그리스도는 그 죄의 결과를 대신 받으셨다. 십자가에서 무수한 시체 대신 그분 한 분이 죽으셨다. 그 은혜를 받으라", "예화_적용":"사 53:8-12로 우리의 죄를 대신 담당하신 그리스도의 희생으로 마무리하라"}
    ],
