    표8_상담적용: [
        {"상황":"세상의 유혹에 쉽게 넘어가는 분", "성경원리":"아리따운 기생의 유혹은 결국 파멸로 이끈다. 매력적으로 보이는 것이 항상 좋은 것이 아니다", "실제적용":"결정하기 전에 이것이 하나님을 기쁘게 하는가를 먼저 물어보는 습관을 기르라"},
        {"상황":"점술이나 신비주의에 관심을 가지는 분", "성경원리":"마술(케샤핌)은 하나님이 금하시는 거짓 영성이다. 그것은 사람을 미혹한다", "실제적용":"하나님만이 참된 영적 안내자이심을 믿고 점술이나 신비주의적 방법에서 떠나 기도와 말씀으로 돌아오라"},
        {"상황":"대중문화의 영향으로 영적 감각이 둔해진 분", "성경원리":"열국을 미혹하는 마술처럼 문화도 영적 분별력을 흐리게 할 수 있다", "실제적용":"일주일 동안 자신이 접하는 미디어와 문화가 신앙에 미치는 영향을 점검하고 영적 분별의 시간을 가져라"}
    ],
