        {"구절":"계 18:23", "연결점":"네 상인들은 땅의 왕족들이요 네 마술로 만국을 미혹하였다", "구분":"신약"},
        {"구절":"약 4:4", "연결점":"세상과 벗이 되고자 하는 자는 하나님과 원수가 됨", "구분":"신약"},
        {"구절":"요 8:44", "연결점":"마귀는 거짓말쟁이요 거짓의 아비이니라", "구분":"신약"}
