        {"대지":"서론", "내용":"'그래도'라는 단어가 이 절의 핵심입니다. 그렇게 강하고 그렇게 많은 동맹이 있어도, 그래도 포로가 되었습니다. 하나님의 심판 앞에 예외는 없습니다.", "예화_적용":""},
        {"대지":"1대지: 포로가 된 테베(예외 없는 심판)", "내용":"감 히 라골라 - 심지어 테베도 포로가 됨. 하나님의 심판은 강약을 가리지 않고 지위를 가리지 않음", "예화_적용":"가장 강했던 나라들도 결국 역사에서 사라진 사례들"},
        {"대지":"2대지: 어린아이와 귀인(심판의 철저함)", "내용":"아이부터 귀인까지 - 심판의 파급력이 사회 전체에 미침. 죄악의 결과는 가장 약한 자에게 더 가혹하게 옴", "예화_적용":"전쟁과 재난이 가장 약한 자들에게 더 큰 고통을 주는 현실 - 죄악의 사회적 책임"},
        {"대지":"3대지: 사슬에 결박된 권세자(권력의 역전)", "내용":"권세자가 사슬에 묶임 - 하나님이 낮추시는 자는 반드시 낮아짐. 한나의 노래처럼 하나님이 역사를 주관하심", "예화_적용":"삼상 2:7-8 - 여호와는 가난하게도 하시고 부하게도 하시며 낮추기도 하시고 높이기도 하심"},
        {"대지":"결론", "내용":"3단계를 마무리하며: 나훔 3:1-10은 죄악의 확실한 결말을 보여줍니다. 하나님의 공의는 반드시 실현됩니다. 이것이 두려움이 아니라 우리에게는 소망의 근거가 됩니다.", "예화_적용":""}
