        {"교리":"심판의 역전", "설명":"강자가 약자가 되고 피난처가 피난처를 구하는 완전한 역전 - 하나님의 주권적 심판", "관련구절":"사 24:20, 렘 25:15-16"},
        {"교리":"정신적 혼란의 심판", "설명":"육체적 멸망 이전에 정신적 공황이 먼저 옴 - 하나님이 적군에게 혼란을 주심", "관련구절":"신 28:28, 숙 12:4"},
        {"교리":"피난처이신 하나님", "설명":"니느웨가 마오즈(피난처)를 찾으나 참된 피난처는 하나님뿐임", "관련구절":"시 46:1, 시 91:2"}
