        {"상황":"자신의 힘과 능력을 과신하다 실패한 성도", "성경원리":"강자도 혼란에 빠지게 하시는 하나님의 주권을 인정하고 겸손히 나아감(잠 3:5-6)", "실제적용":"자기 의존에서 하나님 의존으로 전환하는 구체적인 삶의 패턴 변화"}
