        {"상황":"재물이나 안전망이 갑자기 사라져 불안한 성도", "성경원리":"세상의 요새는 쉽게 무너지나 하나님은 영원한 반석이심(시 62:6-7)", "실제적용":"빌 4:11-13의 바울처럼 풍부와 궁핍에 처할 줄 아는 영적 훈련 권면"}
