        {"항목":"메소포타미아 메뚜기 재해", "내용":"고대 근동에서 메뚜기떼는 가장 두려운 재앙 중 하나. 출애굽 재앙의 기억과 연결되는 이미지", "목회적활용":"하나님의 심판 도구가 얼마나 다양하고 압도적인지를 보여줌"}
