        {"항목":"메뚜기의 탈피 행동", "내용":"메뚜기는 온도가 오르면 날개가 발달하여 급격히 이동함. 상인들이 위기 시 재빨리 떠나는 것과 유사", "목회적활용":"위기 시 이익만 챙기고 떠나는 상업적 관계의 피상성"},
        {"항목":"앗수르 상업망의 붕괴", "내용":"BC 612년 니느웨 멸망 후 앗수르 상업망이 바벨론에 흡수됨. 수백 년간 쌓은 상업 체계가 순식간에 붕괴", "목회적활용":"세상적 성취는 영원하지 않음의 역사적 교훈"}
