        {"대지":"결론", "내용":"세상의 번영은 허물처럼 사라질 수 있습니다. 진정한 부는 하나님 나라 안에 있습니다. 우리가 무엇에 투자하는지가 우리의 실제 가치관을 드러냅니다.", "예화_적용":""}
