        {"대지":"결론", "내용":"위기 때 떠나지 않는 지도자, 양을 위해 목숨 버리는 선한 목자 예수 그리스도가 우리의 진정한 지도자입니다. 우리도 그분을 본받아 위기에 더욱 헌신하는 지도자가 되어야 합니다.", "예화_적용":""}
